"""Ledger model: Entry, ParseError, parse and the shared amount/line formatting."""

import datetime
import decimal
import re
from dataclasses import dataclass
from decimal import Decimal

# Exact decimal arithmetic regardless of how many digits an amount has.
CONTEXT = decimal.Context(
    prec=decimal.MAX_PREC, Emax=decimal.MAX_EMAX, Emin=decimal.MIN_EMIN, traps=[decimal.InvalidOperation]
)

_DATE_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_AMOUNT_RE = re.compile(r"[+-]?[0-9]+(?:\.[0-9]{1,2})?")
_SEPARATOR_RE = re.compile(r"[ \t]+")
_CENT = Decimal("0.01")


class ParseError(ValueError):
    """A bad ledger line. ``line`` is the 1-based line number."""

    def __init__(self, line, message):
        super().__init__("line %d: %s" % (line, message))
        self.line = line
        self.message = message


@dataclass(frozen=True)
class Entry:
    date: datetime.date
    category: str
    amount: Decimal
    note: str = ""


def format_amount(amount):
    """Render an amount with exactly two decimals, never as ``-0.00``."""
    q = CONTEXT.quantize(Decimal(amount), _CENT)
    if q == 0:
        q = Decimal("0.00")
    return format(q, "f")


def format_entry(entry):
    """Render ``DATE CATEGORY AMOUNT[ NOTE]``."""
    text = "%s %s %s" % (entry.date.isoformat(), entry.category, format_amount(entry.amount))
    if entry.note:
        text += " " + entry.note
    return text


def parse_line(raw, number):
    """Parse one ledger line; return an Entry, or None for a blank/comment line."""
    line = raw[:-1] if raw.endswith("\r") else raw
    line = line.strip(" \t")
    if not line or line.startswith("#"):
        return None
    fields = _SEPARATOR_RE.split(line, maxsplit=3)
    if len(fields) < 3:
        raise ParseError(number, "expected DATE CATEGORY AMOUNT [NOTE], got %r" % line)
    date_text, category, amount_text = fields[0], fields[1], fields[2]
    note = fields[3] if len(fields) == 4 else ""
    if not _DATE_RE.fullmatch(date_text):
        raise ParseError(number, "invalid date %r" % date_text)
    try:
        date = datetime.date(int(date_text[:4]), int(date_text[5:7]), int(date_text[8:10]))
    except ValueError:
        raise ParseError(number, "invalid date %r" % date_text) from None
    if not _AMOUNT_RE.fullmatch(amount_text):
        raise ParseError(number, "invalid amount %r" % amount_text)
    return Entry(date, category.lower(), Decimal(amount_text), note)


def parse(text):
    """Parse ledger text into a list of Entry, in file order."""
    if text.startswith("﻿"):
        text = text[1:]
    entries = []
    for number, raw in enumerate(text.split("\n"), 1):
        entry = parse_line(raw, number)
        if entry is not None:
            entries.append(entry)
    return entries
"""The ``pennywise`` command line."""

import argparse
import csv
import datetime
import io
import json
import os
import re
import sys

from .aggregate import balance, by_category, by_month, filter_entries
from .model import ParseError, format_amount, format_entry, parse, parse_line

_VALUE_OPTIONS = frozenset(["--category", "--since", "--until", "--by", "--format"])
_DATE_ARG_RE = re.compile(r"[0-9]{4}-[0-9]{2}-[0-9]{2}")
_FIELD_BREAKS = " \t\r\n"


def _date_arg(text):
    if _DATE_ARG_RE.fullmatch(text):
        try:
            return datetime.date(int(text[:4]), int(text[5:7]), int(text[8:10]))
        except ValueError:
            pass
    raise argparse.ArgumentTypeError("invalid date %r (expected YYYY-MM-DD)" % text)


def _build_parser():
    parser = argparse.ArgumentParser(
        prog="pennywise", description="Read a plain-text household ledger and report where the money went."
    )
    sub = parser.add_subparsers(dest="command", metavar="COMMAND")
    sub.required = True

    def command(name, help_text):
        return sub.add_parser(name, help=help_text, description=help_text, allow_abbrev=False)

    p = command("balance", "print the total of all amounts")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("summary", "print totals per category or month")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--by", choices=["category", "month"], default="category")
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("list", "print entries, oldest first")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--category", metavar="C")
    p.add_argument("--since", metavar="DATE", type=_date_arg)
    p.add_argument("--until", metavar="DATE", type=_date_arg)
    p.add_argument("--json", action="store_true", help="print JSON")

    p = command("add", "append an entry to a ledger file")
    p.add_argument("file", metavar="FILE", help="ledger file (created if missing)")
    p.add_argument("date", metavar="DATE")
    p.add_argument("category", metavar="CATEGORY")
    p.add_argument("amount", metavar="AMOUNT")
    p.add_argument("note", metavar="NOTE", nargs="?", default="")

    p = command("export", "print entries as CSV")
    p.add_argument("file", metavar="FILE", help="ledger file, or - for standard input")
    p.add_argument("--format", choices=["csv"], default="csv")
    return parser


def _normalise_argv(argv):
    """Let option values and `add` operands start with a dash (``-x``, ``-abc``)."""
    out = []
    i = 0
    while i < len(argv):
        tok = argv[i]
        if tok == "--":
            out.extend(argv[i:])
            break
        if tok in _VALUE_OPTIONS and i + 1 < len(argv) and argv[i + 1].startswith("-") and argv[i + 1] != "--":
            out.append(tok + "=" + argv[i + 1])
            i += 2
            continue
        out.append(tok)
        i += 1
    if (
        out[:1] == ["add"]
        and len(out) > 1
        and out[1] not in ("-h", "--help")
        and "--" not in out
    ):
        out.insert(1, "--")
    return out


class _CannotRead(Exception):
    pass


def _read_ledger(path):
    try:
        if path == "-":
            stream = sys.stdin
            if stream is None:
                raise OSError("standard input is closed")
            buffer = getattr(stream, "buffer", None)
            return buffer.read().decode("utf-8") if buffer is not None else stream.read()
        with open(path, "rb") as handle:
            return handle.read().decode("utf-8")
    except (OSError, UnicodeDecodeError) as err:
        name = "standard input" if path == "-" else path
        raise _CannotRead("cannot read %s: %s" % (name, err)) from None


def _load(path):
    return parse(_read_ledger(path))


def _json(obj):
    return json.dumps(obj) + "\n"


def _cmd_balance(args):
    total = format_amount(balance(_load(args.file)))
    return _json({"balance": total}) if args.json else total + "\n"


def _cmd_summary(args):
    entries = _load(args.file)
    totals = by_month(entries) if args.by == "month" else by_category(entries)
    shown = {name: format_amount(total) for name, total in sorted(totals.items())}
    if args.json:
        return _json(shown)
    return "".join("%s  %s\n" % item for item in shown.items())


def _listed(args):
    entries = filter_entries(
        _load(args.file),
        getattr(args, "category", None),
        getattr(args, "since", None),
        getattr(args, "until", None),
    )
    return sorted(entries, key=lambda e: e.date)  # stable: same-day entries keep file order


def _cmd_list(args):
    entries = _listed(args)
    if args.json:
        return _json(
            [
                {"date": e.date.isoformat(), "category": e.category, "amount": format_amount(e.amount), "note": e.note}
                for e in entries
            ]
        )
    return "".join(format_entry(e) + "\n" for e in entries)


def _cmd_export(args):
    entries = _listed(args)
    buffer = io.StringIO()
    writer = csv.writer(buffer, lineterminator="\n")
    writer.writerow(["date", "category", "amount", "note"])
    for e in entries:
        writer.writerow([e.date.isoformat(), e.category, format_amount(e.amount), e.note])
    return buffer.getvalue()


def _cmd_add(args):
    path = args.file
    if path == "-":
        raise _CannotRead("add needs a file, not standard input")
    try:
        with open(path, "rb") as handle:
            existing = handle.read()
    except FileNotFoundError:
        existing = b""
    except OSError as err:
        raise _CannotRead("cannot read %s: %s" % (path, err)) from None
    needs_newline = bool(existing) and not existing.endswith(b"\n")
    number = existing.count(b"\n") + (1 if needs_newline else 0) + 1

    for label, value in (("date", args.date), ("category", args.category), ("amount", args.amount)):
        if not value or any(ch in value for ch in _FIELD_BREAKS):
            raise ParseError(number, "invalid %s %r" % (label, value))
    if "\n" in args.note or "\r" in args.note:
        raise ParseError(number, "note must be a single line")
    line = "%s %s %s" % (args.date, args.category, args.amount)
    if args.note:
        line += " " + args.note
    entry = parse_line(line, number)
    if entry is None:
        raise ParseError(number, "invalid date %r" % args.date)
    canonical = format_entry(entry)
    try:
        payload = (("\n" if needs_newline else "") + canonical + "\n").encode("utf-8")
    except UnicodeEncodeError:
        raise ParseError(number, "entry is not valid text") from None
    try:
        with open(path, "ab") as handle:
            handle.write(payload)
    except OSError as err:
        raise _CannotRead("cannot write %s: %s" % (path, err)) from None
    return canonical + "\n"


_COMMANDS = {
    "balance": _cmd_balance,
    "summary": _cmd_summary,
    "list": _cmd_list,
    "add": _cmd_add,
    "export": _cmd_export,
}


def _emit(text):
    """Write stdout; a closed or full stdout is not a traceback."""
    try:
        sys.stdout.write(text)
        sys.stdout.flush()
    except (OSError, ValueError, UnicodeEncodeError) as err:
        try:  # keep interpreter shutdown from flushing the same bytes again
            fd = os.open(os.devnull, os.O_WRONLY)
            os.dup2(fd, sys.stdout.fileno())
        except (OSError, ValueError, AttributeError):
            pass
        if not isinstance(err, BrokenPipeError):
            print("pennywise: cannot write output: %s" % err, file=sys.stderr)
        return False
    return True


def main(argv=None):
    """Run the CLI; returns the exit status (0 ok, 1 ledger mistake, 2 usage/IO)."""
    args_in = list(sys.argv[1:] if argv is None else argv)
    parser = _build_parser()
    try:
        args = parser.parse_args(_normalise_argv(args_in))
    except SystemExit as exit_:
        code = exit_.code
        return code if isinstance(code, int) else (0 if code is None else 2)
    try:
        output = _COMMANDS[args.command](args)
    except ParseError as err:
        print("pennywise: %s" % err, file=sys.stderr)
        return 1
    except _CannotRead as err:
        print("pennywise: %s" % err, file=sys.stderr)
        return 2
    return 0 if _emit(output) else 2
